20251120180036	{"-- Add missing columns to files table\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"originalName\\" TEXT;\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"bucket\\" TEXT DEFAULT 'files';\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"url\\" TEXT;\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"description\\" TEXT;\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"visibility\\" TEXT DEFAULT 'public';\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"version\\" INTEGER DEFAULT 1;\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"previousVersionId\\" TEXT;\nALTER TABLE \\"files\\" ADD COLUMN IF NOT EXISTS \\"updatedAt\\" TIMESTAMP DEFAULT CURRENT_TIMESTAMP;\n\n-- Create file_links table for multi-entity linking\nCREATE TABLE IF NOT EXISTS \\"file_links\\" (\n    \\"id\\" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,\n    \\"fileId\\" TEXT NOT NULL,\n    \\"targetType\\" TEXT NOT NULL,\n    \\"targetId\\" TEXT NOT NULL,\n    \\"createdAt\\" TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Add foreign key constraints (only if they don't exist)\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'file_links_fileId_fkey') THEN\n        ALTER TABLE \\"file_links\\" ADD CONSTRAINT \\"file_links_fileId_fkey\\" FOREIGN KEY (\\"fileId\\") REFERENCES \\"files\\"(\\"id\\") ON DELETE CASCADE;\n    END IF;\nEND $$;\n\n-- Add indexes for performance (only if they don't exist)\nCREATE INDEX IF NOT EXISTS \\"files_organizationId_idx\\" ON \\"files\\"(\\"organizationId\\");\nCREATE INDEX IF NOT EXISTS \\"files_uploadedById_idx\\" ON \\"files\\"(\\"uploadedById\\");\nCREATE INDEX IF NOT EXISTS \\"files_visibility_idx\\" ON \\"files\\"(\\"visibility\\");\nCREATE INDEX IF NOT EXISTS \\"files_mimeType_idx\\" ON \\"files\\"(\\"mimeType\\");\nCREATE INDEX IF NOT EXISTS \\"files_tags_idx\\" ON \\"files\\" USING GIN(\\"tags\\");\n\nCREATE INDEX IF NOT EXISTS \\"file_links_fileId_idx\\" ON \\"file_links\\"(\\"fileId\\");\nCREATE INDEX IF NOT EXISTS \\"file_links_targetType_targetId_idx\\" ON \\"file_links\\"(\\"targetType\\", \\"targetId\\");\n\n-- Add unique constraint on file_links (only if it doesn't exist)\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'file_links_fileId_targetType_targetId_key') THEN\n        ALTER TABLE \\"file_links\\" ADD CONSTRAINT \\"file_links_fileId_targetType_targetId_key\\" UNIQUE (\\"fileId\\", \\"targetType\\", \\"targetId\\");\n    END IF;\nEND $$;\n\n-- Enable RLS on file_links\nALTER TABLE \\"file_links\\" ENABLE ROW LEVEL SECURITY;"}	add_files_system_missing_columns_and_table	byrne.saar@gmail.com	\N	\N
