--
-- Name: users Admins can create users; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can create users" ON public.users FOR INSERT TO authenticated WITH CHECK (("organizationId" IN ( SELECT orr."organizationId"
   FROM (public.user_roles ur
     JOIN public.organization_roles orr ON ((ur."roleId" = orr.id)))
  WHERE ((ur."userId" = (auth.uid())::text) AND (orr.name = 'Admin'::text)))));


--
-- Name: forms Admins can delete forms; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can delete forms" ON public.forms FOR DELETE TO authenticated USING (("organizationId" IN ( SELECT orr."organizationId"
   FROM (public.user_roles ur
     JOIN public.organization_roles orr ON ((ur."roleId" = orr.id)))
  WHERE ((ur."userId" = (auth.uid())::text) AND (orr.name = 'Admin'::text)))));


--
-- Name: person_organizations Admins can delete person links; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can delete person links" ON public.person_organizations FOR DELETE TO authenticated USING (("organizationId" IN ( SELECT orr."organizationId"
   FROM (public.user_roles ur
     JOIN public.organization_roles orr ON ((ur."roleId" = orr.id)))
  WHERE ((ur."userId" = (auth.uid())::text) AND (orr.name = 'Admin'::text)))));


--
-- Name: persons Admins can delete persons; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can delete persons" ON public.persons FOR DELETE TO authenticated USING ((id IN ( SELECT po."personId"
   FROM (((public.person_organizations po
     JOIN public.users u ON ((po."organizationId" = u."organizationId")))
     JOIN public.user_roles ur ON ((u.id = ur."userId")))
     JOIN public.organization_roles orr ON ((ur."roleId" = orr.id)))
  WHERE ((u.id = (auth.uid())::text) AND (orr.name = 'Admin'::text)))));


