--
-- Name: objects Allow authenticated users to upload chat files; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Allow authenticated users to upload chat files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'files'::text) AND ((storage.foldername(name))[1] = 'chats'::text)));


--
-- Name: objects Allow authenticated users to view chat files; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Allow authenticated users to view chat files" ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'files'::text) AND ((storage.foldername(name))[1] = 'chats'::text)));


